def fill_history(apps, schema_editor):
    """
    Dados antigos:
    - congela o nome dos produtos já vendidos;
    - usa a última alteração como data de fechamento dos pedidos encerrados;
    - separa "Plataforma: X | obs" das observações para o novo campo platform.
    """
    OrderItem = apps.get_model('restaurante', 'OrderItem')
    Order = apps.get_model('restaurante', 'Order')
    for item in OrderItem.objects.select_related('product').filter(product_name=''):
        item.product_name = item.product.name
        item.save(update_fields=['product_name'])
    for order in Order.objects.filter(status__in=['finalizado', 'cancelado'], closed_at__isnull=True):
        order.closed_at = order.updated_at
        order.save(update_fields=['closed_at'])
    for order in Order.objects.filter(observacoes__startswith=PLATFORM_PREFIX):
        rest = order.observacoes[len(PLATFORM_PREFIX):].strip()
        platform, _, notes = rest.partition('|')
        order.platform = platform.strip()[:40]
        order.observacoes = notes.strip()
        order.save(update_fields=['platform', 'observacoes'])


